"""Generates the synthetic motion fixture covers in this directory (no third-party images).

Usage: python -I make-fixtures.py <out-dir>      (needs numpy and pillow, as in motion/prepare)

  stage.jpg      1600x1000 (16:10, cropped to 16:9): a concert stage, light beams, a crowd in front
  poster.jpg     1080x1350 (4:5, blurred extension): a drawn portrait with title bars, like an event poster
  landscape.jpg  2200x1000 (2.2:1, cropped): layered hills at dusk, for a deep depth range
  flat.jpg       1920x1080 (16:9): an almost uniform dark wash with no edges, the worst case for motion gates
  portrait.jpg   1800x1100 (cropped to 16:9): a painted head-and-shoulders portrait lit from the left in a
                 dim warm room (a made-up face, no photograph), for the face presets in crop mode
  vivid.png      1122x1402 RGBA PNG (blurred extension): a loud graphic event poster, saturated colour fields
                 covered in small coloured lettering. Encoded to 4:2:0 video, the chroma of such fine coloured
                 detail is lost, which is what made frame 0 look unlike an RGB cover (the frame-0 regression)

Deterministic: fixed seeds, so the committed files can be regenerated byte for byte with the same libraries.
"""

import os
import sys

import numpy as np
from PIL import Image, ImageDraw, ImageFilter


def gradient(w, h, stops):
    """Vertical gradient through [(pos, (r, g, b)), ...]."""
    y = np.linspace(0, 1, h)[:, None]
    out = np.zeros((h, w, 3), np.float32)
    for c in range(3):
        out[..., c] = np.interp(y, [p for p, _ in stops], [col[c] for _, col in stops])
    return out


def noise(w, h, seed, scale):
    rng = np.random.default_rng(seed)
    small = rng.random((max(2, h // scale), max(2, w // scale))).astype(np.float32)
    return np.asarray(Image.fromarray(small).resize((w, h), Image.BICUBIC), np.float32)


def glow(w, h, cx, cy, rx, ry):
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32)
    return np.exp(-(((xs - cx) / rx) ** 2 + ((ys - cy) / ry) ** 2))


def to_image(arr):
    return Image.fromarray(np.clip(arr, 0, 255).astype(np.uint8))


def stage(path):
    w, h = 1600, 1000
    img = gradient(w, h, [(0, (12, 8, 30)), (0.55, (58, 20, 82)), (0.72, (150, 50, 110)), (1, (30, 10, 30))])
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32)
    for i, (x0, col) in enumerate(
        [(250, (255, 170, 90)), (560, (120, 160, 255)), (800, (255, 230, 200)), (1040, (120, 160, 255)), (1350, (255, 170, 90))]
    ):
        angle = (i - 2) * 0.22
        dx = xs - (x0 + np.tan(angle) * ys)
        width = 18 + ys * 0.16
        beam = np.exp(-(dx / width) ** 2) * np.clip(ys / 120, 0, 1) * np.exp(-ys / 1100)
        img += beam[..., None] * np.array(col, np.float32) * 0.55
    img += glow(w, h, 800, 640, 700, 60)[..., None] * np.array([255, 140, 120], np.float32) * 0.5
    rng = np.random.default_rng(7)
    for _ in range(40):  # stage lights, out of focus
        cx, cy, r = rng.uniform(100, 1500), rng.uniform(540, 660), rng.uniform(6, 16)
        img += glow(w, h, cx, cy, r, r)[..., None] * np.array([255, 210, 160], np.float32) * 0.8
    im = to_image(img)
    d = ImageDraw.Draw(im)
    for row, (base, size, shade) in enumerate([(870, 46, 22), (930, 60, 12), (1010, 80, 4)]):
        x = -40 + row * 37
        while x < w + 80:
            s = size * rng.uniform(0.85, 1.15)
            hy = base - s * 1.4 + rng.uniform(-12, 12)
            d.ellipse([x - s * 0.42, hy - s * 0.55, x + s * 0.42, hy + s * 0.55], fill=(shade, shade, shade + 6))
            d.ellipse([x - s * 1.05, hy + s * 0.35, x + s * 1.05, hy + s * 2.6], fill=(shade, shade, shade + 6))
            if rng.random() < 0.18:  # a raised hand
                d.line([x + s * 0.6, hy + s * 0.6, x + s * 0.9, hy - s * 1.6], fill=(shade, shade, shade + 6), width=int(s * 0.28))
            x += s * rng.uniform(1.3, 1.8)
    im = im.filter(ImageFilter.GaussianBlur(0.8))
    grain = (noise(w, h, 3, 1) - 0.5) * 10
    im = to_image(np.asarray(im, np.float32) + grain[..., None])
    im.save(path, quality=90, subsampling=0)


def poster(path):
    w, h = 1080, 1350
    img = gradient(w, h, [(0, (238, 214, 186)), (0.6, (214, 140, 100)), (1, (96, 44, 46))])
    img += glow(w, h, 540, 520, 380, 380)[..., None] * np.array([40, 30, 10], np.float32)
    im = to_image(img + (noise(w, h, 11, 3)[..., None] - 0.5) * 8)
    d = ImageDraw.Draw(im)
    d.ellipse([200, 140, 880, 820], fill=(244, 176, 96))  # sun disc behind the head
    cx, cy = 540, 520
    d.ellipse([cx - 330, cy + 260, cx + 330, cy + 900], fill=(48, 40, 70))  # shoulders, dark jacket
    d.rectangle([cx - 70, cy + 140, cx + 70, cy + 320], fill=(200, 140, 110))  # neck
    d.ellipse([cx - 190, cy - 270, cx + 190, cy + 40], fill=(40, 26, 24))  # hair
    d.ellipse([cx - 150, cy - 190, cx + 150, cy + 210], fill=(226, 172, 140))  # face
    d.chord([cx - 165, cy - 250, cx + 165, cy - 20], 180, 360, fill=(40, 26, 24))  # fringe
    for sx in (-1, 1):
        ex = cx + sx * 62
        d.ellipse([ex - 40, cy - 30, ex + 40, cy + 18], fill=(200, 140, 112))  # eye socket shade
        d.ellipse([ex - 30, cy - 18, ex + 30, cy + 10], fill=(250, 246, 240))  # eye white
        d.ellipse([ex - 14, cy - 18, ex + 14, cy + 10], fill=(60, 40, 30))  # iris
        d.ellipse([ex - 6, cy - 10, ex + 6, cy + 2], fill=(10, 8, 8))  # pupil
        d.line([ex - 42, cy - 52, ex + 38, cy - 58 + sx * 0], fill=(52, 32, 26), width=12)  # brow
    d.polygon([(cx, cy + 10), (cx - 26, cy + 92), (cx + 26, cy + 92)], fill=(198, 140, 112))  # nose shade
    d.ellipse([cx - 28, cy + 80, cx + 28, cy + 100], fill=(180, 120, 100))
    d.chord([cx - 62, cy + 112, cx + 62, cy + 160], 0, 180, fill=(170, 70, 72))  # mouth
    d.line([cx - 62, cy + 128, cx + 62, cy + 128], fill=(120, 50, 52), width=4)
    im = im.filter(ImageFilter.GaussianBlur(2.2))
    d = ImageDraw.Draw(im)
    for i, (bw, bh) in enumerate([(760, 74), (540, 40), (420, 30)]):  # title, date and venue bars
        y = 1100 + sum(b[1] + 24 for b in [(760, 74), (540, 40), (420, 30)][:i])
        d.rounded_rectangle([(w - bw) // 2, y, (w + bw) // 2, y + bh], radius=bh // 3, fill=(250, 238, 222))
    im.save(path, quality=90, subsampling=0)


def landscape(path):
    w, h = 2200, 1000
    img = gradient(w, h, [(0, (40, 46, 96)), (0.45, (214, 120, 110)), (0.62, (252, 196, 140)), (1, (60, 40, 60))])
    img += glow(w, h, 1500, 560, 260, 160)[..., None] * np.array([255, 220, 160], np.float32) * 0.7
    ys = np.arange(h, dtype=np.float32)[:, None]
    xs = np.arange(w, dtype=np.float32)
    layers = [(560, 70, (150, 104, 130)), (640, 90, (110, 74, 108)), (730, 110, (74, 50, 82)), (830, 130, (44, 30, 56)), (930, 120, (20, 14, 30))]
    for i, (base, amp, col) in enumerate(layers):
        rng = np.random.default_rng(100 + i)
        ridge = base + sum(
            amp / (k + 1) * np.sin(xs / (420 / (k + 1)) * rng.uniform(0.6, 1.4) + rng.uniform(0, 6.28)) for k in range(4)
        )
        mask = Image.fromarray(((ys >= ridge[None, :]) * 255).astype(np.uint8))
        mask = np.asarray(mask.filter(ImageFilter.GaussianBlur(1.2 + (4 - i) * 0.8)), np.float32) / 255.0
        img = img * (1 - mask[..., None]) + np.array(col, np.float32) * mask[..., None]
    im = to_image(img + (noise(w, h, 21, 2)[..., None] - 0.5) * 7)
    im.save(path, quality=90, subsampling=0)


def flat(path):
    w, h = 1920, 1080
    img = gradient(w, h, [(0, (46, 36, 40)), (1, (30, 24, 30))])
    img += glow(w, h, 960, 520, 900, 600)[..., None] * np.array([14, 10, 8], np.float32)
    im = to_image(img + (noise(w, h, 31, 4)[..., None] - 0.5) * 3)
    im.save(path, quality=90, subsampling=0)


def portrait(path):
    """A painted, made-up face: shaded with a soft key light from the left, so a face detector finds it."""
    w, h = 1800, 1100
    ys, xs = np.mgrid[0:h, 0:w].astype(np.float32)
    # A dim warm room: a window glow on the left, a darker wall on the right, a few out-of-focus lamps.
    img = gradient(w, h, [(0, (58, 44, 40)), (0.6, (46, 34, 32)), (1, (30, 22, 22))])
    img += glow(w, h, 260, 380, 520, 640)[..., None] * np.array([150, 120, 90], np.float32)
    for cx, cy, r, col in [(1380, 260, 40, (255, 196, 120)), (1520, 330, 26, (255, 180, 110)), (1610, 200, 34, (240, 200, 150))]:
        img += glow(w, h, cx, cy, r, r)[..., None] * np.array(col, np.float32) * 0.55
    img += (noise(w, h, 41, 6)[..., None] - 0.5) * 10

    def ell(cx, cy, rx, ry, soft=2.0):
        r = np.sqrt(((xs - cx) / rx) ** 2 + ((ys - cy) / ry) ** 2)
        return np.clip((1 - r) * min(rx, ry) / soft, 0, 1)

    def paint(mask, col, k=1.0):
        nonlocal img
        m = (mask * k)[..., None]
        img = img * (1 - m) + np.asarray(col, np.float32) * m

    cx, cy = 900, 470  # face centre
    light = np.clip(0.8 + 0.32 * (cx - xs) / 170, 0.5, 1.12)  # key light from the left, falling off to the right
    # Shoulders and a dark knit sweater, a neck in shadow under the jaw.
    paint(ell(cx, 1130, 470, 330, 4), (52, 46, 58))
    sweater = np.clip(0.75 + 0.35 * (cx - xs) / 500, 0.45, 1.1)[..., None] * (0.9 + 0.2 * noise(w, h, 43, 3)[..., None])
    m = ell(cx, 1130, 470, 330, 4)[..., None]
    img = img * (1 - m) + np.array([52, 46, 58], np.float32) * sweater * m
    neck = ell(cx, 760, 86, 170, 6)
    m = neck[..., None]
    img = img * (1 - m) + np.array([150, 100, 80], np.float32)[None, None, :] * light[..., None] * m
    img *= (1 - 0.45 * ell(cx + 10, 700, 110, 70, 30))[..., None] ** 1.0 * 1  # shadow under the jaw
    # Hair behind the head.
    hair_back = ell(cx + 10, 420, 250, 300, 8)
    paint(hair_back, (34, 24, 22))
    # The face: skin with the key light, a warm bounce on the shadow side, cheeks.
    face = ell(cx, cy, 165, 225, 5)
    rr = np.clip(((xs - cx) / 165) ** 2 + ((ys - cy) / 225) ** 2, 0, 1)
    skin = np.array([240, 184, 150], np.float32)[None, None, :] * (light * (0.8 + 0.2 * np.sqrt(1 - rr)))[..., None]
    skin += glow(w, h, cx + 150, cy + 60, 90, 140)[..., None] * np.array([18, 6, 0], np.float32)
    skin += (glow(w, h, cx - 70, cy + 70, 50, 34) + glow(w, h, cx + 70, cy + 70, 50, 34))[..., None] * np.array([10, -3, -4], np.float32)
    m = face[..., None]
    img = img * (1 - m) + skin * m
    # Eye sockets, brows, eyes.
    for sx in (-1, 1):
        ex, ey = cx + sx * 68, cy - 22
        img *= (1 - 0.18 * ell(ex, ey - 4, 52, 30, 18))[..., None]
        paint(ell(ex, ey - 46, 52, 9, 3), (58, 38, 30), 0.9)  # brow
        paint(ell(ex, ey, 30, 13, 2), (236, 226, 216))  # eye white
        paint(ell(ex + 2, ey, 12, 12, 1.5), (78, 52, 36))  # iris
        paint(ell(ex + 2, ey, 5.5, 5.5, 1.2), (14, 10, 10))  # pupil
        paint(ell(ex - 3, ey - 4, 2.5, 2.5, 1), (255, 250, 245))  # catch light
        paint(ell(ex, ey - 9, 33, 5, 2), (70, 44, 36), 0.7)  # upper lid line
    # Nose: a shadow on the right of the bridge and under the tip, a highlight on the left.
    img *= (1 - 0.22 * ell(cx + 16, cy + 40, 16, 58, 10))[..., None]
    img *= (1 - 0.3 * ell(cx + 4, cy + 92, 30, 12, 6))[..., None]
    img += ell(cx - 8, cy + 50, 8, 34, 6)[..., None] * np.array([22, 18, 14], np.float32)
    # Lips.
    paint(ell(cx, cy + 140, 50, 13, 3), (176, 92, 88))
    paint(ell(cx, cy + 133, 46, 3, 1.5), (110, 52, 52), 0.8)
    img += ell(cx - 10, cy + 146, 18, 4, 2)[..., None] * np.array([20, 14, 12], np.float32)
    # A fringe and hair falling at the sides.
    paint(ell(cx - 30, cy - 205, 200, 78, 6), (38, 27, 24))
    paint(ell(cx - 182, cy - 20, 40, 190, 6), (36, 26, 23))
    paint(ell(cx + 184, cy - 10, 38, 200, 6), (30, 22, 20))
    img += (noise(w, h, 47, 2)[..., None] - 0.5) * 8 * hair_back[..., None]
    im = to_image(img).filter(ImageFilter.GaussianBlur(1.2))
    im = to_image(np.asarray(im, np.float32) + (noise(w, h, 49, 1)[..., None] - 0.5) * 6)
    im.save(path, quality=90, subsampling=0)


def vivid(path):
    """Saturated colour fields with rows of small, thin, coloured glyphs (no faces, no photograph)."""
    w, h = 1122, 1402
    rng = np.random.default_rng(61)
    bands = [  # (top, bottom, field colour, lettering colour, glyph height, stroke)
        (0, 300, (226, 0, 26), (0, 40, 255), 22, 3),
        (300, 520, (255, 214, 0), (214, 0, 160), 16, 2),
        (520, 900, (0, 70, 230), (255, 40, 0), 28, 3),
        (900, 1120, (0, 190, 90), (240, 0, 200), 14, 2),
        (1120, 1402, (150, 0, 200), (255, 230, 0), 18, 2),
    ]
    im = Image.new("RGBA", (w, h), (0, 0, 0, 255))
    d = ImageDraw.Draw(im)
    for top, bottom, field, ink, gh, stroke in bands:
        d.rectangle([0, top, w, bottom], fill=field + (255,))
        y = top + 14
        while y + gh < bottom - 10:
            x = 24 + int(rng.integers(0, 30))
            while x < w - 40:
                for _ in range(int(rng.integers(2, 9))):  # a word: glyphs of strokes, bowls and bars
                    gw = int(gh * rng.uniform(0.45, 0.8))
                    kind = int(rng.integers(0, 4))
                    box = [x, y, x + gw, y + gh]
                    if kind == 0:
                        d.ellipse(box, outline=ink + (255,), width=stroke)
                    elif kind == 1:
                        d.line([x, y, x, y + gh], fill=ink + (255,), width=stroke)
                        d.line([x, y + gh // 2, x + gw, y + gh // 2], fill=ink + (255,), width=stroke)
                        d.line([x + gw, y, x + gw, y + gh], fill=ink + (255,), width=stroke)
                    elif kind == 2:
                        d.line([x, y + gh, x + gw // 2, y, x + gw, y + gh], fill=ink + (255,), width=stroke)
                    else:
                        d.rectangle(box, outline=ink + (255,), width=stroke)
                    x += gw + stroke + 3
                x += gh
            y += gh + int(gh * 0.6)
    im.save(path, optimize=True)


if __name__ == "__main__":
    out = sys.argv[1] if len(sys.argv) > 1 else os.path.dirname(os.path.abspath(__file__))
    stage(os.path.join(out, "stage.jpg"))
    poster(os.path.join(out, "poster.jpg"))
    landscape(os.path.join(out, "landscape.jpg"))
    flat(os.path.join(out, "flat.jpg"))
    portrait(os.path.join(out, "portrait.jpg"))
    vivid(os.path.join(out, "vivid.png"))
